param([ValidateSet('cross-prepare','cross-conflict','cross-restore','cross-final')][string]$Action,[string]$Nonce,[switch]$Recovery)
$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -ne 'MU-CLEAN-LAB' -or $Nonce -notmatch '^[a-f0-9]{64}$' -or -not([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'A bound isolated administrator cross-user operation is required'}
$caseId=$Nonce.Substring(0,32);$directory='C:\MuLab\backup-user-'+$caseId;$file='C:\MuLab\approved\backup-user-'+$caseId+'-config.json';$sourceSid=(Get-LocalUser MuLabUser).SID.Value
function Receipt($value){$value.nonce=$Nonce;[IO.File]::WriteAllText(('C:\MuLab\approved\adoption-'+$Action+'.json'),($value|ConvertTo-Json -Depth 12 -Compress));$value}
if($Action -eq 'cross-prepare'){
 $name='MuBkp_'+$caseId.Substring(0,8);if((Get-LocalUser $name -ErrorAction SilentlyContinue) -or (Test-Path -LiteralPath $directory) -or (Test-Path -LiteralPath $file)){throw 'Existing cross-user case is preserved; initialization cannot reset accounts'}
 $seed=[IO.File]::ReadAllText('C:\MuLab\approved\adoption-seed-result.json')|ConvertFrom-Json;$export=[IO.File]::ReadAllText(('C:\MuLab\public\backup-cross-export-'+$Nonce+'.json'))|ConvertFrom-Json
 if(-not $seed.complete -or $export.id -ne $seed.nested.config.id -or $export.originalPlatformId -ne $seed.nested.platformId){throw 'Source cross-user identity changed'}
 $vm=Get-VM -Id ([guid]$seed.nested.platformId);$disk=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sourceSid+'/vms/'+$export.id+'/disk.vhdx');if($vm.State -ne 'Off' -or (Get-FileHash -LiteralPath $disk).Hash.ToLowerInvariant() -ne $export.sha256){throw 'Stopped original source digest changed'}
 $password='MuBkp!'+[guid]::NewGuid().ToString('N')+'a7Z';$user=New-LocalUser -Name $name -Password (ConvertTo-SecureString $password -AsPlainText -Force) -PasswordNeverExpires -Description ('MuBackup '+$caseId);Add-LocalGroupMember -SID S-1-5-32-545 -Member ('MU-CLEAN-LAB\'+$name)
 $acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetAccessRuleProtection($true,$false);$acl.SetOwner([Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'));foreach($sid in @($user.SID.Value,'S-1-5-18','S-1-5-32-544')){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($sid),[Security.AccessControl.FileSystemRights]::FullControl,([Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [Security.AccessControl.InheritanceFlags]::ObjectInherit),[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow))};[IO.Directory]::CreateDirectory($directory,$acl)|Out-Null
 [IO.File]::Copy(('C:\MuLab\public\backup-cross-'+$Nonce+'.mucwin'),(Join-Path $directory archive.mucwin),$false);[IO.File]::Copy(('C:\MuLab\public\backup-cross-source-'+$Nonce+'\credentials.dpapi'),(Join-Path $directory source-key.dpapi),$false)
 $config=@{caseId=$caseId;userName=$name;userSid=$user.SID.Value;sourceSid=$sourceSid;directory=$directory;config=$export.config;canary=$export.canary;originalPlatformId=$export.originalPlatformId;diskBytes=$export.bytes;diskSha256=$export.sha256;sourceDisk=$disk;sourcePrivateKey=('C:\MuLab\public\adoption-runtime\mu-win-'+$export.id.Replace('-','')+'\management');nodeSha256=(Get-FileHash C:\MuLab\product\resources\node\node.exe).Hash.ToLowerInvariant();clientSha256=(Get-FileHash C:\MuLab\backup-cross-target.mjs).Hash.ToLowerInvariant()}
 if(-not(Test-Path -LiteralPath $config.sourcePrivateKey -PathType Leaf)){throw 'Original management key is missing'}
 [IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 12 -Compress));[IO.File]::WriteAllText(('C:\MuLab\private\backup-user-'+$caseId+'-credentials.json'),(@{caseId=$caseId;userSid=$user.SID.Value;password=$password}|ConvertTo-Json -Compress))
 $permissions=@();foreach($item in @(@{path='C:\MuLab';inherit=$false;directory=$true},@{path='C:\MuLab\approved';inherit=$false;directory=$true},@{path='C:\MuLab\product';inherit=$true;directory=$true},@{path='C:\MuLab\backup-cross-target.mjs';inherit=$false;directory=$false},@{path=$file;inherit=$false;directory=$false})){
  $existing=Get-Acl -LiteralPath $item.path;$before=$existing.Sddl;$flags=if($item.inherit){[Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [Security.AccessControl.InheritanceFlags]::ObjectInherit}else{[Security.AccessControl.InheritanceFlags]::None};$existing.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($user.SID,[Security.AccessControl.FileSystemRights]::ReadAndExecute,$flags,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow));Set-Acl -LiteralPath $item.path -AclObject $existing;$permissions+=@{path=$item.path;directory=$item.directory;before=$before;after=(Get-Acl -LiteralPath $item.path).Sddl}
 };[IO.File]::WriteAllText(('C:\MuLab\private\backup-user-'+$caseId+'-permissions.json'),($permissions|ConvertTo-Json -Depth 5 -Compress))
 $launcher='C:\MuLab\approved\backup-user-'+$caseId+'-station.exe';Add-Type -TypeDefinition ([IO.File]::ReadAllText('C:\MuLab\BackupUserStation.cs')) -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll') -OutputAssembly $launcher -OutputType ConsoleApplication
 return (Receipt @{complete=$true;ordinary=$true;sourceSid=$sourceSid;userSid=$user.SID.Value})
}
$config=[IO.File]::ReadAllText($file)|ConvertFrom-Json;if($config.caseId -cne $caseId -or $config.directory -cne $directory -or (Get-LocalUser $config.userName).SID.Value -ne $config.userSid -or $config.sourceSid -ne $sourceSid -or @(Get-LocalGroupMember -SID S-1-5-32-544|Where-Object{$_.SID.Value -eq $config.userSid}).Count){throw 'Cross-user account or case binding changed'}
if($Action -eq 'cross-final'){
 if(@(Get-VM).Count){throw 'Nested VM remains'};foreach($sid in @($config.sourceSid,$config.userSid)){$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sid);$ledger=[IO.File]::ReadAllText((Join-Path $root vms.json))|ConvertFrom-Json;if(@($ledger.records.PSObject.Properties).Count -or [IO.File]::ReadAllText((Join-Path $root vms.json)) -cne [IO.File]::ReadAllText((Join-Path $root vms.backup.json))){throw 'A cross-user protected allocation remains'}}
 Disable-LocalUser -Name $config.userName;$permissions=[IO.File]::ReadAllText(('C:\MuLab\private\backup-user-'+$caseId+'-permissions.json'))|ConvertFrom-Json;foreach($item in $permissions){$acl=Get-Acl -LiteralPath $item.path;if($acl.Sddl -ceq $item.before){continue};if($acl.Sddl -cne $item.after){throw 'Shared fixture permissions changed; retained for inspection'};$acl.SetSecurityDescriptorSddlForm($item.before);Set-Acl -LiteralPath $item.path -AclObject $acl};return (Receipt @{complete=$true;targetDisabled=$true;sharedFixturePermissionsRestored=$true;sourceSid=$sourceSid;targetSid=$config.userSid})
}
$phase=if($Recovery){'recover'}elseif($Action -eq 'cross-conflict'){'conflict'}else{'restore'};$prefix=Join-Path $directory $phase
if((Test-Path -LiteralPath ($prefix+'-owner.json')) -or (Test-Path -LiteralPath ($prefix+'-result.json'))){throw 'An existing cross-user phase must be inspected instead of restarted'}
$station=if($Recovery){$config.recoveryLauncher}else{'C:\MuLab\approved\backup-user-'+$caseId+'-station.exe'}
$launcher=Start-Process -FilePath $station -ArgumentList @($caseId,$phase) -WindowStyle Hidden -RedirectStandardOutput ($prefix+'-station-out.log') -RedirectStandardError ($prefix+'-station-error.log') -PassThru;$null=$launcher.Handle
$until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path -LiteralPath ($prefix+'-owner.json'))){if($launcher.HasExited){throw 'Cross-user launcher exited before publishing its owner'};if([DateTime]::UtcNow -gt $until){throw 'Cross-user launcher remains pending'};Start-Sleep -Milliseconds 200}
$owner=[IO.File]::ReadAllText($prefix+'-owner.json')|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
if($owner.caseId -cne $caseId -or $owner.phase -ne $phase -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne 'C:\MuLab\product\resources\node\node.exe' -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $config.userSid){throw 'Cross-user owner process identity changed'}
$process=Get-Process -Id $owner.pid;$null=$process.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$meta=[IO.File]::ReadAllText((Join-Path $bin current.json))|ConvertFrom-Json;$broker=Join-Path $bin $meta.brokerFile;if((Get-FileHash $broker).Hash.ToLowerInvariant() -ne $meta.brokerSha256){throw 'Cross-user broker changed'}
$agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ($prefix+'-broker-out.log') -RedirectStandardError ($prefix+'-broker-error.log') -PassThru;$null=$agent.Handle;$audited=$false;$until=[DateTime]::UtcNow.AddMinutes(30)
while(-not $launcher.WaitForExit(250)){
 if([DateTime]::UtcNow -gt $until){throw 'Cross-user phase remains live; preserve its exact process'}
 if($phase -in @('restore','recover') -and -not $audited -and (Test-Path -LiteralPath ($prefix+'-audit-request.json'))){
  $request=[IO.File]::ReadAllText($prefix+'-audit-request.json')|ConvertFrom-Json;if($request.nonce -cne $owner.nonce -or $request.pid -ne $owner.pid -or $request.id -ne $config.config.id){throw 'Target owner audit request changed'}
  $vm=Get-VM -Id ([guid]$request.platformId);$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$disk=Join-Path $root ('vms/'+$request.id+'/disk.vhdx');$drives=@(Get-VMHardDiskDrive -VM $vm);$ledger=[IO.File]::ReadAllText((Join-Path $root vms.json))|ConvertFrom-Json
  $expectedHash=if($Recovery){$config.recoveryDiskSha256}else{$config.diskSha256}
  if($vm.State -ne 'Off' -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -cne $disk -or $ledger.ownerSid -ne $config.userSid -or $ledger.records.($request.id).ownerSid -ne $config.userSid -or (Get-FileHash -LiteralPath $disk).Hash.ToLowerInvariant() -ne $expectedHash){throw 'New SID protected ownership or original disk changed'}
  [IO.File]::WriteAllText(('C:\MuLab\approved\backup-user-'+$caseId+'-audit.json'),(@{nonce=$owner.nonce;newOwnerConfirmed=$true;id=$request.id;platformId=$request.platformId;userSid=$config.userSid}|ConvertTo-Json -Compress));$audited=$true
 }
}
if(-not $process.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Cross-user controller or broker exit is unconfirmed'}
$result=[IO.File]::ReadAllText($prefix+'-result.json')|ConvertFrom-Json;if($result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce -or -not $result.complete -or $launcher.ExitCode -ne 0){throw ('Cross-user phase failed: '+($result.error|ConvertTo-Json -Compress))}
if($phase -in @('restore','recover')){if(-not $audited){throw 'Independent owner audit was not performed'};[IO.File]::Copy((Join-Path $directory app/credentials.dpapi),('C:\MuLab\approved\backup-user-'+$caseId+'-target-key.dpapi'),$false)}
$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true -Force;Receipt $result
